// Task 0064: a pack named on a data= line is registered at the position of its line among the data folders. Written
// from the task text alone. The packs are generated by the independent builder of edenarchive/testsupport from
// generated folders; no game files are involved.
//
// The main check is a comparison: a pack made from folder B, listed between folders A and C, must give the same
// winners, contents and override report as folder B itself at that place.

#include "vfstestutil.hpp"

#include <components/vfs/archivefactory.hpp>
#include <components/vfs/edenarchive.hpp>

#include <eapackmodel.hpp>
#include <eautil.hpp>

#include <gtest/gtest.h>

#include <algorithm>
#include <cctype>
#include <string>
#include <utility>
#include <vector>

namespace VFS
{
    namespace
    {
        using namespace testing;
        using namespace VFSTest;

        using NamedContent = std::pair<std::string, std::string>;

        std::string lowerCase(std::string text)
        {
            std::transform(text.begin(), text.end(), text.begin(),
                [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
            return text;
        }

        // Bytes of a pack holding the given files (names stored as given, so give them normalized).
        std::string packBytes(const std::vector<NamedContent>& files)
        {
            EdenTest::PackSpec pack;
            for (const auto& [name, content] : files)
            {
                EdenTest::EntrySpec entry;
                entry.mPath = name;
                entry.mContent = EdenTest::bytesOf(content);
                pack.mEntries.push_back(std::move(entry));
            }
            const EdenTest::Bytes bytes = EdenTest::buildPack(pack);
            return std::string(bytes.begin(), bytes.end());
        }

        // Every file below a folder as (normalized relative name, content), in a stable order.
        std::vector<NamedContent> readFolder(const std::filesystem::path& folder)
        {
            std::vector<NamedContent> result;
            for (const auto& entry : std::filesystem::recursive_directory_iterator(folder))
            {
                if (!entry.is_regular_file())
                    continue;
                std::ifstream stream(entry.path(), std::ios::binary);
                result.emplace_back(
                    lowerCase(std::filesystem::relative(entry.path(), folder).generic_string()), readAll(stream));
            }
            std::sort(result.begin(), result.end());
            return result;
        }

        struct OverrideSummary
        {
            std::string mPath;
            std::size_t mWinner = 0;
            std::vector<std::size_t> mLosers;

            bool operator==(const OverrideSummary& other) const
            {
                return mPath == other.mPath && mWinner == other.mWinner && mLosers == other.mLosers;
            }
        };

        std::vector<OverrideSummary> summarize(const Manager& vfs)
        {
            std::vector<OverrideSummary> result;
            for (const Override& item : vfs.getOverrides())
            {
                OverrideSummary summary;
                summary.mPath = item.mPath.value();
                summary.mWinner = item.mWinner.mArchive;
                for (const Provider& loser : item.mLosers)
                    summary.mLosers.push_back(loser.mArchive);
                result.push_back(std::move(summary));
            }
            std::sort(result.begin(), result.end(),
                [](const OverrideSummary& l, const OverrideSummary& r) { return l.mPath < r.mPath; });
            return result;
        }

        std::string describe(const std::vector<OverrideSummary>& items)
        {
            std::string out;
            for (const OverrideSummary& item : items)
            {
                out += item.mPath + " <- " + std::to_string(item.mWinner) + " over";
                for (const std::size_t loser : item.mLosers)
                    out += " " + std::to_string(loser);
                out += "\n";
            }
            return out;
        }

        struct VFSPackPlacementTest : Test
        {
            ScratchDir mTemp;
            std::filesystem::path mA;
            std::filesystem::path mB;
            std::filesystem::path mC;
            std::filesystem::path mPack; // made from mB

            void SetUp() override
            {
                clearArchiveFactories();
                registerBethesdaArchiveKinds();
                registerEdenArchiveFactory();

                mA = mTemp.makeDir("a");
                mB = mTemp.makeDir("b");
                mC = mTemp.makeDir("c");

                writeFile(mA / "shared" / "all.txt", "A-all");
                writeFile(mA / "a_only.txt", "A-only");
                writeFile(mA / "meshes" / "wall.nif", "A-wall");
                writeFile(mA / "nested" / "deep" / "ab.txt", "A-ab");

                writeFile(mB / "shared" / "all.txt", "B-all");
                writeFile(mB / "b_only.txt", "B-only");
                writeFile(mB / "Meshes" / "Wall.NIF", "B-wall");
                writeFile(mB / "nested" / "deep" / "ab.txt", "B-ab");
                writeFile(mB / "nested" / "deep" / "bc.txt", "B-bc");

                writeFile(mC / "shared" / "all.txt", "C-all");
                writeFile(mC / "c_only.txt", "C-only");
                writeFile(mC / "nested" / "deep" / "bc.txt", "C-bc");

                // A fallback BSA that overlaps everything, kept in folder A.
                writeBsa(mA / "base.bsa",
                    { { "shared/all.txt", "bsa-all" }, { "bsa_only.txt", "bsa-only" }, { "b_only.txt", "bsa-b" },
                        { "meshes/wall.nif", "bsa-wall" } });

                mPack = mTemp.path() / "b.edenpak";
                writeFile(mPack, packBytes(readFolder(mB)));
            }

            void TearDown() override { clearArchiveFactories(); }

            // The list with folder B replaced by its pack.
            static Files::PathContainer withPack(const Files::PathContainer& folders,
                const std::filesystem::path& folderB, const std::filesystem::path& pack)
            {
                Files::PathContainer result = folders;
                for (std::filesystem::path& path : result)
                {
                    if (path == folderB)
                        path = pack;
                }
                return result;
            }

            static void registerList(Manager& vfs, const Files::PathContainer& list,
                const std::vector<std::string>& archives, bool useLooseFiles = true)
            {
                const Files::Collections collections(list);
                registerArchives(&vfs, collections, archives, useLooseFiles, nullptr);
            }

            void expectSameAsFolder(const Files::PathContainer& folders, const std::vector<std::string>& archives)
            {
                Manager expected;
                registerList(expected, folders, archives);
                Manager actual;
                registerList(actual, withPack(folders, mB, mPack), archives);

                EXPECT_EQ(actual.getArchiveCount(), expected.getArchiveCount());

                std::vector<std::string> expectedNames = listAllNames(expected);
                std::vector<std::string> actualNames = listAllNames(actual);
                std::sort(expectedNames.begin(), expectedNames.end());
                std::sort(actualNames.begin(), actualNames.end());
                EXPECT_EQ(actualNames, expectedNames);
                EXPECT_THAT(expectedNames, Contains("b_only.txt"));

                for (const std::string& name : expectedNames)
                {
                    EXPECT_EQ(contentOf(actual, name), contentOf(expected, name)) << name;
                }

                const std::vector<OverrideSummary> expectedOverrides = summarize(expected);
                const std::vector<OverrideSummary> actualOverrides = summarize(actual);
                EXPECT_FALSE(expectedOverrides.empty());
                EXPECT_EQ(actualOverrides, expectedOverrides) << "expected:\n"
                                                              << describe(expectedOverrides) << "actual:\n"
                                                              << describe(actualOverrides);
            }
        };

        // ---- (a) the pack stands where its line stands ----

        TEST_F(VFSPackPlacementTest, packBetweenFoldersShouldActLikeTheFolderThere)
        {
            expectSameAsFolder({ mA, mB, mC }, {});
        }

        TEST_F(VFSPackPlacementTest, packFirstShouldActLikeTheFolderThere)
        {
            expectSameAsFolder({ mB, mA, mC }, {});
        }

        TEST_F(VFSPackPlacementTest, packLastShouldActLikeTheFolderThere)
        {
            expectSameAsFolder({ mA, mC, mB }, {});
        }

        TEST_F(VFSPackPlacementTest, packBetweenFoldersWithFallbackArchiveShouldActLikeTheFolderThere)
        {
            expectSameAsFolder({ mA, mB, mC }, { "base.bsa" });
        }

        TEST_F(VFSPackPlacementTest, packFirstWithFallbackArchiveShouldActLikeTheFolderThere)
        {
            expectSameAsFolder({ mB, mA, mC }, { "base.bsa" });
        }

        TEST_F(VFSPackPlacementTest, packLastWithFallbackArchiveShouldActLikeTheFolderThere)
        {
            expectSameAsFolder({ mA, mC, mB }, { "base.bsa" });
        }

        TEST_F(VFSPackPlacementTest, packShouldWinAndLoseByItsPosition)
        {
            // A fixed expectation, so that the comparison above cannot pass with both sides wrong.
            Manager vfs;
            registerList(vfs, { mA, mPack, mC }, {});
            EXPECT_EQ(contentOf(vfs, "shared/all.txt"), "C-all");
            EXPECT_EQ(contentOf(vfs, "nested/deep/ab.txt"), "B-ab"); // the pack beats A below it
            EXPECT_EQ(contentOf(vfs, "nested/deep/bc.txt"), "C-bc"); // C above beats the pack
            EXPECT_EQ(contentOf(vfs, "meshes/wall.nif"), "B-wall");
            EXPECT_EQ(contentOf(vfs, "b_only.txt"), "B-only");
            EXPECT_EQ(contentOf(vfs, "a_only.txt"), "A-only");
            EXPECT_EQ(vfs.getArchiveCount(), 3u);
        }

        // ---- (b) packs against fallback archives ----

        TEST_F(VFSPackPlacementTest, packOnDataLineShouldBeatFallbackArchive)
        {
            Manager vfs;
            registerList(vfs, { mA, mPack }, { "base.bsa" });
            EXPECT_EQ(contentOf(vfs, "b_only.txt"), "B-only");
            EXPECT_EQ(contentOf(vfs, "meshes/wall.nif"), "B-wall");
            EXPECT_EQ(contentOf(vfs, "bsa_only.txt"), "bsa-only");
        }

        TEST_F(VFSPackPlacementTest, packNamedInFallbackArchiveShouldLoseToEveryFolder)
        {
            writeFile(mA / "b.edenpak", packBytes(readFolder(mB)));

            Manager vfs;
            registerList(vfs, { mA, mC }, { "base.bsa", "b.edenpak" });
            EXPECT_EQ(contentOf(vfs, "shared/all.txt"), "C-all");
            EXPECT_EQ(contentOf(vfs, "nested/deep/ab.txt"), "A-ab"); // folder A beats the pack
            EXPECT_EQ(contentOf(vfs, "nested/deep/bc.txt"), "C-bc");
            EXPECT_EQ(contentOf(vfs, "meshes/wall.nif"), "A-wall");
            // Only the pack and the BSA provide it: the later fallback archive wins, as before.
            EXPECT_EQ(contentOf(vfs, "b_only.txt"), "B-only");
        }

        // ---- (c) a file that is named like a pack but is not one ----

        TEST_F(VFSPackPlacementTest, notAPackNamedEdenpakShouldMakeRegisterArchivesThrowNamingTheFile)
        {
            const std::filesystem::path bad = mTemp.path() / "notapack.edenpak";
            writeFile(bad, "this is plain text, not an Eden Archive");

            Manager vfs;
            try
            {
                registerList(vfs, { mA, bad, mC }, {});
                FAIL() << "registerArchives accepted a file that is not a pack";
            }
            catch (const std::runtime_error& e)
            {
                EXPECT_NE(std::string(e.what()).find("notapack.edenpak"), std::string::npos) << e.what();
            }
        }

        TEST_F(VFSPackPlacementTest, brokenPackShouldMakeRegisterArchivesThrowNamingTheFile)
        {
            const std::filesystem::path bad = mTemp.path() / "broken.edenpak";
            const std::string good = packBytes(readFolder(mB));
            writeFile(bad, good.substr(0, 1000)); // starts with the magic, then ends too early

            Manager vfs;
            try
            {
                registerList(vfs, { mA, bad }, {});
                FAIL() << "registerArchives accepted a truncated pack";
            }
            catch (const std::runtime_error& e)
            {
                EXPECT_NE(std::string(e.what()).find("broken.edenpak"), std::string::npos) << e.what();
            }
        }

        // ---- (d) the same pack twice ----

        TEST_F(VFSPackPlacementTest, samePackListedTwiceShouldBeRegisteredOnce)
        {
            Manager once;
            registerList(once, { mA, mPack, mC }, {});
            Manager twice;
            registerList(twice, { mA, mPack, mPack, mC }, {});

            EXPECT_EQ(twice.getArchiveCount(), 3u);
            EXPECT_EQ(twice.getArchiveCount(), once.getArchiveCount());
            EXPECT_EQ(summarize(twice), summarize(once));
            EXPECT_EQ(contentOf(twice, "nested/deep/ab.txt"), "B-ab");
        }

        // ---- (e) without loose files ----

        TEST_F(VFSPackPlacementTest, withoutLooseFilesPackEntriesShouldNotBeRegistered)
        {
            Manager vfs;
            registerList(vfs, { mA, mPack }, {}, false);
            EXPECT_EQ(vfs.getArchiveCount(), 0u);
            EXPECT_FALSE(vfs.exists(Path::Normalized("b_only.txt")));
            EXPECT_THAT(listAllNames(vfs), IsEmpty());
        }

        // ---- (f) content files at the top level of a pack ----

        TEST_F(VFSPackPlacementTest, findContentFilesInArchiveShouldListTopLevelContentFilesInIndexOrder)
        {
            const std::filesystem::path path = mTemp.path() / "content.edenpak";
            writeFile(path,
                packBytes({ { "a.esp", "1" }, { "b.esm", "2" }, { "c.omwaddon", "3" }, { "d.omwscripts", "4" },
                    { "e.txt", "5" }, { "sub/f.esp", "6" }, { "g.omwgame", "7" }, { "h.project", "8" },
                    { "notes.esp.txt", "9" }, { "sub/deeper/i.esm", "10" } }));

            const std::unique_ptr<Archive> archive = makeEdenArchive(path, nullptr);
            ASSERT_NE(archive, nullptr);
            EXPECT_THAT(findContentFilesInArchive(*archive),
                ElementsAre("a.esp", "b.esm", "c.omwaddon", "d.omwscripts", "g.omwgame", "h.project"));
        }

        TEST_F(VFSPackPlacementTest, findContentFilesInArchiveShouldBeEmptyWithoutContentFiles)
        {
            const std::unique_ptr<Archive> archive = makeEdenArchive(mPack, nullptr);
            ASSERT_NE(archive, nullptr);
            EXPECT_THAT(findContentFilesInArchive(*archive), IsEmpty());
        }
    }
}
